from AlgorithmImports import *
from collections import defaultdict


class StrategySystemAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 200
        self.spy_sma = self.SMA(self.spy, self.sma_period, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.aapl, 14, MovingAverageType.Wilders,
                                 Resolution.Daily)

        self.previous_close = {}
        self.previous_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        current_bars = {}

        for ticker, symbol in self.symbols.items():
            if not data.ContainsKey(symbol):
                return

            bar = data[symbol]
            if bar is None:
                return

            current_bars[ticker] = bar

        spy_bar = current_bars["SPY"]
        aapl_bar = current_bars["AAPL"]

        if self.spy in self.previous_close:
            if spy_bar.Close < self.previous_close[self.spy]:
                pass

        if self.aapl in self.previous_close:
            if aapl_bar.Close < self.previous_close[self.aapl]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
        else:
            self.aapl_red_streak = 0

        self.spy_sma.Update(spy_bar.EndTime, spy_bar.Close)
        self.aapl_rsi.Update(aapl_bar.EndTime, aapl_bar.Close)

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self._store_state(spy_bar, aapl_bar)
            return

        spy_sma_value = self.spy_sma.Current.Value
        aapl_rsi_value = self.aapl_rsi.Current.Value

        spy_close_crossed_below = (
            self.previous_close.get(self.spy) is not None
            and self.previous_sma is not None
            and self.previous_close[self.spy] <= self.previous_sma
            and spy_bar.Close > self.previous_close[self.spy]
            and spy_close_crossed_below_level(
                self.previous_close[self.spy],
                self.previous_sma,
                spy_bar.Close,
                spy_sma_value
            )
        )

        spy_close_crossed_above = (
            self.previous_close.get(self.spy) is not None
            and self.previous_sma is not None
            and self.previous_close[self.spy] <= self.previous_sma
            and spy_bar.Close > spy_sma_value
        )

        spy_close_crossed_below = (
            self.previous_close.get(self.spy) is not None
            and self.previous_sma is not None
            and self.previous_close[self.spy] >= self.previous_sma
            and spy_bar.Close < spy_sma_value
        )

        if self.strategy_a_shares > 0 and spy_close_crossed_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and aapl_rsi_value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_close_crossed_above:
            shares = int(
                (self.Portfolio.TotalPortfolioValue * 0.40) / spy_bar.Close
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / aapl_bar.Close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

        self._store_state(spy_bar, aapl_bar)
        self.previous_sma = spy_sma_value

    def _store_state(self, spy_bar, aapl_bar):
        self.previous_close[self.spy] = spy_bar.Close
        self.previous_close[self.aapl] = aapl_bar.Close


def spy_close_crossed_below_level(previous_close, previous_sma,
                                  current_close, current_sma):
    return previous_close >= previous_sma and current_close < current_sma
