from AlgorithmImports import *
import math


class ExactStrategySystem(QCAlgorithm):
    SMA_PERIOD = 200

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker,
                Resolution.Daily,
                Market.USA,
                True,
                DataNormalizationMode.Adjusted,
                True
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, self.SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            close = data.Bars[symbol].Close
            previous_close = self.previous_closes.get(symbol)

            if ticker == "AAPL" and previous_close is not None:
                if close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_closes[symbol] = close

        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        spy_sma_today = self.spy_sma.Current.Value
        spy_sma_yesterday = self.spy_sma.Previous.Value

        spy_crosses_below = (
            spy_close <= spy_sma_today and
            self.spy_sma.Previous is not None and
            self.previous_spy_close <= spy_sma_yesterday
        )

        spy_crosses_above = (
            spy_close > spy_sma_today and
            self.previous_spy_close <= spy_sma_yesterday
        )

        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            quantity = int(
                math.floor(
                    0.40 * self.Portfolio.TotalPortfolioValue / spy_close
                )
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            investment = 20000
            if self.Portfolio.Cash >= investment:
                quantity = int(math.floor(investment / aapl_close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

        self.previous_spy_close = spy_close
