from AlgorithmImports import *
from collections import deque
from math import floor


class ExactStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(
                ticker, Resolution.Daily
            ).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma_period = 14
        self.rsi_period = 14

        self.spy_closes = deque(maxlen=self.sma_period + 1)
        self.aapl_closes = deque(maxlen=4)

        self.spy_sma = SimpleMovingAverage(self.sma_period)
        self.aapl_rsi = RelativeStrengthIndex(
            self.rsi_period, MovingAverageType.Wilders
        )

        self.spy_lot = 0
        self.aapl_lot = 0
        self.aapl_red_streak = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_rsi = None

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.ContainsKey(symbol) or data[symbol] is None:
                bars[ticker] = None
            else:
                bars[ticker] = data[symbol]

        # Continuously compute market-state quantities when data is available.
        spy_bar = bars["SPY"]
        if spy_bar is not None:
            self.spy_closes.append(float(spy_bar.Close))
            self.spy_sma.Update(spy_bar.EndTime, float(spy_bar.Close))

        aapl_bar = bars["AAPL"]
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)

            if self.aapl_closes:
                previous_close = self.aapl_closes[-1]
                if aapl_close < previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_closes.append(aapl_close)
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        # Rule evaluation is skipped if any subscribed ticker is missing.
        if any(bar is None for bar in bars.values()):
            self._update_previous_values()
            return

        spy_ready = self.spy_sma.IsReady and len(self.spy_closes) >= self.sma_period + 1
        aapl_ready = self.aapl_rsi.IsReady and len(self.aapl_closes) >= 4

        # Sell rules are evaluated before buy rules.
        if spy_ready and self.spy_lot > 0:
            current_spy_close = float(spy_bar.Close)
            current_spy_sma = float(self.spy_sma.Current.Value)

            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close >= self.previous_spy_sma
                and current_spy_close < current_spy_sma
            ):
                self.MarketOrder(self.spy, -self.spy_lot)
                self.spy_lot = 0

        if aapl_ready and self.aapl_lot > 0:
            current_rsi = float(self.aapl_rsi.Current.Value)

            if current_rsi > 60:
                self.MarketOrder(self.aapl, -self.aapl_lot)
                self.aapl_lot = 0

        # Buy rules are evaluated only while each private lot is empty.
        if spy_ready and self.spy_lot == 0:
            current_spy_close = float(spy_bar.Close)
            current_spy_sma = float(self.spy_sma.Current.Value)

            if (
                self.previous_spy_close is not None
                and self.previous_spy_sma is not None
                and self.previous_spy_close <= self.previous_spy_sma
                and current_spy_close > current_spy_sma
            ):
                shares = floor(
                    0.40 * self.Portfolio.TotalPortfolioValue
                    / current_spy_close
                )
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.spy_lot = shares

        if aapl_ready and self.aapl_lot == 0:
            if self.aapl_red_streak >= 3:
                current_aapl_close = float(aapl_bar.Close)
                if self.Portfolio.Cash >= 20000:
                    shares = floor(20000 / current_aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.aapl_lot = shares

        self._update_previous_values()

    def _update_previous_values(self):
        if self.spy_sma.IsReady and self.spy_closes:
            self.previous_spy_close = self.spy_closes[-1]
            self.previous_spy_sma = float(self.spy_sma.Current.Value)

        if self.aapl_rsi.IsReady:
            self.previous_aapl_rsi = float(self.aapl_rsi.Current.Value)
