class ExactStrategyAlgorithm(QCAlgorithm):
    SMA_PERIOD = 200
    RSI_PERIOD = 14

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, self.SMA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_close = {}
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.SetWarmUp(self.SMA_PERIOD + 1, Resolution.Daily)

    def OnData(self, data: Slice):
        current_closes = {}

        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            bar = data.Bars[symbol]
            current_closes[ticker] = bar.Close

        if "AAPL" in current_closes:
            aapl_close = current_closes["AAPL"]
            previous_aapl_close = self.previous_close.get("AAPL")

            if previous_aapl_close is not None:
                if aapl_close < previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_close["AAPL"] = aapl_close

        for ticker, close in current_closes.items():
            if ticker != "AAPL":
                self.previous_close[ticker] = close

        if self.IsWarmingUp:
            return

        if len(current_closes) != len(self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = current_closes["SPY"]
        current_spy_sma = self.spy_sma.Current.Value

        spy_crossed_above = (
            self.previous_close.get("SPY") is not None
            and self.previous_spy_sma is not None
            and self.previous_close["SPY"] <= self.previous_spy_sma
            and spy_close > current_spy_sma
        )

        spy_crossed_below = (
            self.previous_close.get("SPY") is not None
            and self.previous_spy_sma is not None
            and self.previous_close["SPY"] >= self.previous_spy_sma
            and spy_close < current_spy_sma
        )

        aapl_rsi_above_60 = self.aapl_rsi.Current.Value > 60

        if self.strategy_a_shares > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and aapl_rsi_above_60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_crossed_above:
            shares = floor(
                0.40 * self.Portfolio.TotalPortfolioValue / spy_close
            )
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                shares = floor(20_000 / current_closes["AAPL"])
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

        self.previous_spy_sma = current_spy_sma

