        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        required = [self.spy, self.aapl] + [
            symbol for ticker, symbol in self.symbols.items()
            if ticker not in ["SPY", "AAPL"]
        ]

        if any(symbol not in data.Bars for symbol in required):
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self._update_state(spy_close, aapl_close)
            return

        spy_sma_value = self.spy_sma.Current.Value
        aapl_rsi_value = self.aapl_rsi.Current.Value

        spy_crosses_below = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_close > self.previous_spy_sma
        )

        spy_crosses_above = (
            self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_close < self.previous_spy_sma
        )

        aapl_red_three_days = self.aapl_red_streak >= 3
        aapl_rsi_sell = aapl_rsi_value > 60

        if self.strategy_a_lot > 0 and spy_crosses_above:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and aapl_rsi_sell:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_below:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )
